e2e:
  needs: validate
  uses: ./.github/workflows/e2e.yml
  with:
    caller-repository: ${{ github.repository }}
    caller-ref: ${{ github.sha }}
    source-branch: ${{ github.head_ref }}
    fallback-ref: ${{ vars.E2E_API_FALLBACK_REF }}
  secrets:
    CROSS_REPO_READ_TOKEN: ${{ secrets.CROSS_REPO_READ_TOKEN }}
